import { test, expect } from '@playwright/test';

test.describe('Record Creation - Display Created and Last Modified Dates', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display created and last modified dates for a record', async ({ page }) => {
    // Create a new record
    const createButton = page.getByRole('button', { name: /create record/i });
    await createButton.click();

    const nameInput = page.getByLabel(/record name/i);
    await nameInput.fill('Test Record');

    const descriptionInput = page.getByLabel(/record description/i);
    await descriptionInput.fill('This is a test record');

    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message
    const successMessage = page.getByText(/record created successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify record is listed
    const recordList = page.getByRole('list', { name: /records/i });
    await expect(recordList).toBeVisible();

    // Verify created date is displayed
    const createdDate = page.getByText(/created on/i);
    await expect(createdDate).toBeVisible();

    // Verify last modified date is displayed
    const lastModifiedDate = page.getByText(/last modified on/i);
    await expect(lastModifiedDate).toBeVisible();

    // Verify record details are visible
    const recordItem = page.getByText('Test Record');
    await expect(recordItem).toBeVisible();

    // Verify record details are clickable
    await expect(recordItem).toHaveAttribute('data-testid', /record-item/);
  });

  test('should display created and last modified dates when record is updated', async ({ page }) => {
    // Navigate to record page
    const recordPage = page.getByRole('main', { name: /records/i });
    await recordPage.click();

    // Verify record is listed
    const recordList = page.getByRole('list', { name: /records/i });
    await expect(recordList).toBeVisible();

    // Verify record details are visible
    const recordItem = page.getByText('Test Record');
    await expect(recordItem).toBeVisible();

    // Verify created date is displayed
    const createdDate = page.getByText(/created on/i);
    await expect(createdDate).toBeVisible();

    // Verify last modified date is displayed
    const lastModifiedDate = page.getByText(/last modified on/i);
    await expect(lastModifiedDate).toBeVisible();

    // Update record
    const updateButton = page.getByRole('button', { name: /update/i });
    await updateButton.click();

    const updatedNameInput = page.getByLabel(/record name/i);
    await updatedNameInput.fill('Updated Test Record');

    const updatedDescriptionInput = page.getByLabel(/record description/i);
    await updatedDescriptionInput.fill('Updated description');

    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message
    const successMessage = page.getByText(/record updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify record details are updated
    await expect(recordItem).toContainText('Updated Test Record');

    // Verify created date remains unchanged
    await expect(createdDate).toContainText('created on');

    // Verify last modified date is updated
    await expect(lastModifiedDate).toContainText('last modified on');
  });
});
